<script setup lang="ts">
import { computed, ref } from 'vue'
import { Sigma, RefreshCw, FlaskConical } from 'lucide-vue-next'
import { useQuery } from '../lib/query'
import { api, errorText } from '../lib/api'
import { record, num, pct, stamp } from '../lib/format'
import { useSession } from '../stores/session'
import PageState from '../components/PageState.vue'
import Badge from '../components/Badge.vue'
const q = useQuery<{ registry: { name: string; status: string }[]; name_count: number; note: string; report: Record<string, unknown> | null }>('/api/workspace/factors')
const diag = useQuery<{ report: Record<string, unknown> | null }>('/api/workspace/factor-diagnostics'), session = useSession(), horizon = ref(5), busy = ref(false), message = ref('')
const styles=useQuery<{templates: {id:string;name:string;version:string;description:string;questions:string[];references:{title:string;url:string}[]}[]}>('/api/workspace/research-styles')
const report = computed(() => diag.data.value?.report ?? q.data.value?.report)
const metrics = computed(() => Array.isArray(report.value?.metrics) ? report.value!.metrics.map(record).filter(m => m.horizon === horizon.value) : [])
const fields = computed(() => Array.isArray(report.value?.correlation_fields) ? report.value!.correlation_fields.map(String) : [])
const matrix = computed(() => Array.isArray(report.value?.correlations) ? report.value!.correlations as (number | null)[][] : [])
const samples = computed(() => Array.isArray(report.value?.correlation_dates) ? report.value!.correlation_dates as number[][] : [])
async function run() { if (busy.value) return; busy.value = true; try { await api('/api/workspace/data-jobs', { method: 'POST', body: { task: 'factors', codes: [], request_key: crypto.randomUUID() } }); message.value = '已排入确定性因子诊断队列。完成后点击重新读取；不会自动加入策略。' } catch (e) { message.value = errorText(e) } finally { busy.value = false } }
</script><template><div class="page-heading"><div><span class="eyebrow">FACTOR RESEARCH LAB</span><h1>因子研究</h1><p>先确认数据、相关性与增量价值，再讨论权重。因子数量不是有效性。</p></div><div class="heading-actions"><button class="button" @click="q.reload();diag.reload()"><RefreshCw :size="14"/>重新读取</button><button v-if="session.role === 'admin' || !session.identifier" class="button primary" :disabled="busy" @click="run"><FlaskConical :size="14"/>提交诊断任务</button></div></div><div v-if="message" class="notice" role="status">{{ message }}</div><div class="notice warning-notice">当前所有结果均为研究诊断，不代表样本外合格，不自动改权重或晋升因子。相关性不等于因果。</div><div class="cards"><div class="stat-card"><small>登记名称</small><div class="value">{{ q.data.value?.name_count ?? '—' }}</div><p>不等于独立因子族数量</p></div><div class="stat-card"><small>通过资格验证</small><div class="value">未认定</div><p>需 OOS / 消融 / 人工批准</p></div><div class="stat-card"><small>覆盖标的</small><div class="value">{{ num(report?.instruments ?? record(report?.panel).instruments, 0) }}</div><p>{{ String(report?.source_as_of ?? record(report?.panel).last_date ?? '尚无诊断数据') }}</p></div><div class="stat-card"><small>诊断生成时间</small><p>{{ stamp(String(report?.generated_at ?? '')) }}</p><Badge :value="String(report?.qualification ?? 'not_qualified')"/></div></div><div class="card section"><div class="card-header"><h2><Sigma :size="16"/>因子效果诊断</h2><select v-model.number="horizon" aria-label="因子诊断期限"><option v-for="h in [1,3,5,10]" :key="h" :value="h">{{ h }} 个交易日</option></select></div><PageState :loading="q.loading.value || diag.loading.value" :error="q.error.value || diag.error.value" :empty="!metrics.length" title="尚无该期限的诊断结果" description="先同步足够的历史数据，再运行诊断任务。不会用空数据生成 IC 或相关性。" @retry="q.reload();diag.reload()"><div class="table-scroll"><table><thead><tr><th>因子</th><th>覆盖率</th><th>Rank IC</th><th>ICIR</th><th>分位收益差</th><th>换手诊断</th><th>观测日期数</th></tr></thead><tbody><tr v-for="m in metrics" :key="String(m.factor)"><td class="mono">{{ m.factor }}</td><td>{{ pct(typeof m.coverage === 'number' ? m.coverage : null) }}</td><td>{{ num(m.rank_ic_mean, 4) }}</td><td>{{ num(m.icir, 3) }}</td><td>{{ pct(typeof m.top_bottom_spread === 'number' ? m.top_bottom_spread : null) }}</td><td>{{ pct(typeof m.top_quantile_turnover === 'number' ? m.top_quantile_turnover : null) }}</td><td>{{ m.observation_dates }}</td></tr></tbody></table></div></PageState></div><div v-if="fields.length" class="card section"><div class="card-header"><h2>因子相关性 · Spearman</h2><small>按日期截面计算后平均；悬停显示有效日期数</small></div><div class="table-scroll"><table class="correlation"><thead><tr><th>因子</th><th v-for="f in fields" :key="f">{{ f }}</th></tr></thead><tbody><tr v-for="(f, i) in fields" :key="f"><th>{{ f }}</th><td v-for="(g, j) in fields" :key="g" :title="`有效日期数：${samples[i]?.[j] ?? 0}`">{{ num(matrix[i]?.[j], 2) }}</td></tr></tbody></table></div></div><div class="card section"><div class="card-header"><h2>研究登记表</h2><small>{{ q.data.value?.note }}</small></div><div class="card-body actions"><span v-for="item in q.data.value?.registry" :key="item.name" class="badge mono">{{ item.name }}</span></div></div><div class="card section"><div class="card-header"><h2>风格研究模板</h2><small>方法模板，不冒充真实交易员，不直接成为策略</small></div><div class="card-body template-grid"><article v-for="style in styles.data.value?.templates" :key="style.id" class="template-card"><h3>{{style.name}}</h3><p>{{style.description}}</p><Badge value="pending" :label="'研究假设 · '+style.version"/><details><summary>检查问题与参考来源</summary><p v-for="question in style.questions" :key="question">{{question}}</p><p v-for="reference in style.references" :key="reference.url"><a v-if="reference.url.startsWith('https://github.com/')" :href="reference.url" target="_blank" rel="noopener noreferrer">{{reference.title}}</a><span v-else>{{reference.title}}（文档包内）</span></p></details></article><p v-if="styles.error.value" role="alert">{{styles.error.value}}</p></div></div></template>
